$adminTitle='Job moderation';$adminHeading='Keep opportunity clear and trustworthy.';$adminActive='jobs';$adminLead='Review listings, moderate public visibility, and preserve existing candidate records.';include jobproPath('src/views/admin-start.php');$f=jobproAdminFilters();
